<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            -subj</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/C=GB/ST=London/L=London/O=QuantFinanceHub CA/OU=picluster/CN=s3.quantfinancehub.com&quot;</span></span>
